reservationForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const guestName = document.querySelector("#guestName").value.trim();
  const checkIn = document.querySelector("#checkIn").value;
  const checkOut = document.querySelector("#checkOut").value;
  const occupiedDays = getReservedDays(checkIn, checkOut);

  if (occupiedDays.length < 2) {
    window.alert("La estadía mínima es de 2 días. Revisá la fecha de salida.");
    return;
  }

  const overlap = occupiedDays.some((day) => busyDays.includes(day));
  if (overlap) {
    const confirmed = window.confirm("Hay días que ya figuran ocupados. ¿Querés guardar la reserva igual?");
    if (!confirmed) return;
  }

  const reservation = {
    id: String(Date.now()),
    guestName: guestName || "Reserva confirmada",
    checkIn,
    checkOut,
    days: occupiedDays,
    createdAt: new Date().toISOString(),
  };

  reservations = [reservation, ...reservations];
  busyDays = Array.from(new Set([...busyDays, ...occupiedDays])).sort();

  saveJson(storageKeys.reservations, reservations);
  saveJson(storageKeys.busyDays, busyDays);

  reservationForm.reset();
  renderCalendar();
  renderReservations();
  updateGuestBooking();
  window.alert("Reserva guardada. Esos días ya no aparecen como disponibles.");
});

photoInput.addEventListener("change", async (event) => {
  if (!adminMode) {
    photoInput.value = "";
    window.alert("Solo el administrador puede cargar fotos.");
    return;
  }

  const files = Array.from(event.target.files || []);
  const images = files.filter((file) => file.type.startsWith("image/"));
  if (!images.length) return;

  const loaded = await Promise.all(images.map(readImageFile));
  const prepared = loaded.map((data) => ({ id: createId("photo"), data }));
  await addStoredPhotos(prepared);
  photos = await getStoredPhotos();
  currentPhoto = Math.max(getAllPhotos().length - prepared.length, 0);
  photoInput.value = "";
  renderGallery();
  window.alert("Fotos cargadas correctamente.");
});

