importData.addEventListener("change", async (event) => {
  const file = event.target.files?.[0];
  if (!file) return;

  try {
    const text = await file.text();
    const data = JSON.parse(text);

    busyDays = Array.isArray(data.busyDays) ? data.busyDays : [];
    reservations = Array.isArray(data.reservations) ? data.reservations : [];
    reviews = Array.isArray(data.reviews) ? data.reviews : [];
    reviewCodes = Array.isArray(data.reviewCodes) ? data.reviewCodes : [];

    saveJson(storageKeys.busyDays, busyDays);
    saveJson(storageKeys.reservations, reservations);
    saveJson(storageKeys.reviews, reviews);
    saveJson(storageKeys.reviewCodes, reviewCodes);

    if (Array.isArray(data.photos)) {
      await replaceStoredPhotos(data.photos);
    }

    photos = await getStoredPhotos();
    currentPhoto = 0;
    renderCalendar();
    renderReservations();
    renderGallery();
    renderReviews();
    updateGuestBooking();
    window.alert("Respaldo importado. Ya quedaron restauradas fotos, reservas y reseñas.");
  } catch (error) {
    window.alert("No se pudo importar el respaldo. Revisa que sea el archivo correcto.");
  } finally {
    importData.value = "";
  }
});

reviewForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const code = reviewCodeInput.value.trim().toUpperCase();
  const email = reviewEmail.value.trim().toLowerCase();
  const stars = Number(reviewStars.value);
  const message = reviewMessage.value.trim();

  if (!code || !email || !stars || !message) {
    window.alert("Completá código, correo, estrellas y reseña.");
    return;
  }

  const codeRecord = reviewCodes.find((item) => item.code === code);
  if (!codeRecord) {
    window.alert("Ese código no existe.");
    return;
  }

  if (codeRecord.used) {
    window.alert("Ese código ya fue usado.");
    return;
  }

  const review = {
    id: createId("review"),
    code,
    label: codeRecord.label || "Huesped",
    email,
    stars,
    message,
    approved: false,
    hidden: true,
    createdAt: new Date().toISOString(),
  };

  reviews = [review, ...reviews];
  reviewCodes = reviewCodes.map((item) =>
    item.code === code
      ? {
          ...item,
          used: true,
          usedAt: new Date().toISOString(),
          reviewId: review.id,
        }
      : item
  );

  saveJson(storageKeys.reviews, reviews);
  saveJson(storageKeys.reviewCodes, reviewCodes);
  reviewForm.reset();
  renderReviews();
  window.alert("Gracias. La reseña quedó enviada para revisión.");
});

