function renderGallery() {
  const allPhotos = getAllPhotos();
  photoFrame.innerHTML = "";
  thumbs.innerHTML = "";

  if (!allPhotos.length) {
    const placeholder = document.createElement("div");
    placeholder.className = "placeholder";
    placeholder.textContent = "Subí fotos de la casa, habitaciones, asador, solarium y vistas para que aparezcan acá.";
    photoFrame.appendChild(placeholder);
    photoCounter.textContent = "Sin fotos cargadas";
    prevPhoto.disabled = true;
    nextPhoto.disabled = true;
    deletePhoto.hidden = true;
    deleteAllPhotos.hidden = true;
    return;
  }

  if (currentPhoto < 0 || currentPhoto >= allPhotos.length) {
    currentPhoto = 0;
  }

  const selected = allPhotos[currentPhoto];
  const image = document.createElement("img");
  image.src = selected.data;
  image.alt = `Foto de La Carlota ${currentPhoto + 1}`;
  photoFrame.appendChild(image);

  photoCounter.textContent = `${currentPhoto + 1} de ${allPhotos.length} fotos`;
  prevPhoto.disabled = allPhotos.length < 2;
  nextPhoto.disabled = allPhotos.length < 2;
  deletePhoto.hidden = !adminMode;
  deleteAllPhotos.hidden = !adminMode || !photos.length;

  allPhotos.forEach((photo, index) => {
    const thumb = document.createElement("button");
    thumb.type = "button";
    thumb.className = index === currentPhoto ? "active" : "";
    thumb.setAttribute("aria-label", `Ver foto ${index + 1}`);

    const thumbImage = document.createElement("img");
    thumbImage.src = photo.data;
    thumbImage.alt = "";
    thumb.appendChild(thumbImage);

    thumb.addEventListener("click", () => {
      currentPhoto = index;
      renderGallery();
    });

    thumbs.appendChild(thumb);
  });
}

